import React, { useEffect, useState } from 'react';
import Shimmer from './Shimmer';

const EffectCard = () => {
    const [products, setProducts] = useState([]);
    const [filteredProducts, setFilteredProducts] = useState([]);
    const [searchText, setSearchText] = useState('');
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchProducts = async () => {
            try {
                setIsLoading(true);
                setError(null);

                const res = await fetch('https://fakestoreapi.in/api/products');
                if (!res.ok) {
                    throw new Error(`Failed to fetch: ${res.status} ${res.statusText}`);
                }

                const data = await res.json();
                setProducts(data.products || []);
                setFilteredProducts(data.products || []);
            } catch (err) {
                setError(err.message || 'Something went wrong!');
            } finally {
                setIsLoading(false);
            }
        };

        fetchProducts();
    }, []);

    // Live filtering based on brand or category
    useEffect(() => {
        const filtered = products.filter(product =>
            product.brand.toLowerCase().includes(searchText.toLowerCase()) ||
            product.category.toLowerCase().includes(searchText.toLowerCase())
        );
        setFilteredProducts(filtered);
    }, [searchText, products]);

    if (isLoading) {
        return <Shimmer />;
    }

    if (error) {
        return (
            <div className="container mt-5 text-center">
                <h3 className="text-danger">Error: {error}</h3>
                <p>Please try refreshing the page or check your internet connection.</p>
            </div>
        );
    }

    return (
        <div className="container mt-4">
            {/* Search Bar */}
            <div className="mb-4 d-flex align-items-center gap-2">
                <input
                    type="text"
                    className="form-control p-3 rounded-4 shadow-sm"
                    placeholder="Search by brand or category..."
                    value={searchText}
                    onChange={(e) => setSearchText(e.target.value)}
                />
                {/* Optional Button - Not needed since search is live */}
                <button className='btn btn-primary' disabled>
                    Search
                </button>
            </div>

            {/* Product Cards */}
            <div className="row g-4">
                {filteredProducts.length > 0 ? (
                    filteredProducts.map((product) => (
                        <div className="col-sm-6 col-md-4 col-lg-3" key={product.id}>
                            <div className="card h-100 border-0 shadow rounded-4">
                                <img
                                    src={product.image}
                                    alt={`${product.brand} product`}
                                    className="img-fluid p-4"
                                />
                                <div className="card-body">
                                    <h5 className="card-title fw-semibold text-uppercase">
                                        {product.brand}
                                    </h5>
                                    <span className="badge bg-primary text-light">
                                        {product.category}
                                    </span>
                                </div>
                                <div className="card-footer bg-white border-top-0">
                                    <h6 className="text-success fw-bold fs-5">
                                        ₹{product.price}
                                    </h6>
                                </div>
                            </div>
                        </div>
                    ))
                ) : (
                    <div className="text-center">
                        <h5 className="text-muted">No products found.</h5>
                    </div>
                )}
            </div>
        </div>
    );
};

export default EffectCard;
